def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    seen = [[False] * w for _ in range(h)]
    isolated = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            component = []
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if len(component) == 1 and color != background:
                isolated.append(component[0])

    out = [row[:] for row in grid]
    for r, c in isolated:
        neighbors = []
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dy, c + dx
            if 0 <= nr < h and 0 <= nc < w:
                neighbors.append(grid[nr][nc])

        counts = Counter(x for x in neighbors if x != background)
        if counts:
            color, n = counts.most_common(1)[0]
            if n >= 2:
                out[r][c] = color
            else:
                out[r][c] = background
        else:
            out[r][c] = background

    return out
